1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: grid; place-items: center;
11	    background: #eef0f3; font-family: system-ui, -apple-system, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 92vw); padding: 16px; border-radius: 16px;
15	    background: #1f2329; box-shadow: 0 10px 30px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 72px; margin-bottom: 12px; padding: 0 12px; border-radius: 10px;
19	    background: #2c323a; color: #fff; font-size: 2.2rem;
20	    display: flex; align-items: center; justify-content: flex-end;
21	    overflow: hidden; white-space: nowrap;
22	  }
23	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
24	  button {
25	    height: 60px; border: 0; border-radius: 10px; font-size: 1.3rem;
26	    background: #3a414b; color: #fff; cursor: pointer;
27	  }
28	  button:active { filter: brightness(1.2); }
29	  .op { background: #f59e0b; }
30	  .clear { background: #6b7280; }
31	  .equals { background: #10b981; }
32	  .wide { grid-column: span 2; }
33	</style>
34	</head>
35	<body>
36	<div class="calc">
37	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
38	  <div class="keys">
39	    <button class="clear wide" data-testid="key-clear" data-action="clear">AC</button>
40	    <button class="op" data-testid="key-div" data-op="/">÷</button>
41	    <button class="op" data-testid="key-mul" data-op="*">×</button>
42	    <button data-testid="key-7" data-digit="7">7</button>
43	    <button data-testid="key-8" data-digit="8">8</button>
44	    <button data-testid="key-9" data-digit="9">9</button>
45	    <button class="op" data-testid="key-sub" data-op="-">−</button>
46	    <button data-testid="key-4" data-digit="4">4</button>
47	    <button data-testid="key-5" data-digit="5">5</button>
48	    <button data-testid="key-6" data-digit="6">6</button>
49	    <button class="op" data-testid="key-add" data-op="+">+</button>
50	    <button data-testid="key-1" data-digit="1">1</button>
51	    <button data-testid="key-2" data-digit="2">2</button>
52	    <button data-testid="key-3" data-digit="3">3</button>
53	    <button class="equals" data-testid="key-equals" data-action="equals">=</button>
54	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
55	    <button data-testid="key-dot" data-action="dot">.</button>
56	  </div>
57	</div>
58	<script>
59	  // State: acc = stored left operand, op = pending operator,
60	  // entry = digits being typed (string) or null, value = number shown.
61	  var state = { acc: null, op: null, entry: null, value: 0, error: false };
62	
63	  function compute(a, op, b) {
64	    var r;
65	    if (op === '+') r = a + b;
66	    else if (op === '-') r = a - b;
67	    else if (op === '*') r = a * b;
68	    else r = a / b;
69	    if (!isFinite(r)) return NaN;
70	    return r;
71	  }
72	
73	  // Presentation only: stored values are never rounded. At most 10 significant
74	  // digits, no trailing zeros, exponential only for |n| >= 1e10 or < 1e-9.
75	  function formatNumber(n) {
76	    if (n === 0) return '0';
77	    var r = Number(n.toPrecision(10));
78	    var abs = Math.abs(r);
79	    if (abs >= 1e10 || abs < 1e-9) {
80	      return r.toExponential(9).replace(/\.?0+e/, 'e');
81	    }
82	    var exp = Number(r.toExponential(9).split('e')[1]);
83	    var s = r.toFixed(Math.max(0, 9 - exp));
84	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
85	    return s;
86	  }
87	
88	  function pressDigit(d) {
89	    if (state.error) return;
90	    if (state.entry === null || state.entry === '0') state.entry = d;
91	    else state.entry += d;
92	    state.value = Number(state.entry);
93	  }
94	
95	  function pressDot() {
96	    if (state.error) return;
97	    if (state.entry === null) state.entry = '0';
98	    if (state.entry.indexOf('.') === -1) state.entry += '.';
99	    state.value = Number(state.entry);
100	  }
101	
102	  function resolve() {
103	    if (state.op !== null && state.entry !== null) {
104	      state.value = compute(state.acc, state.op, state.value);
105	      if (isNaN(state.value)) state.error = true;
106	    }
107	  }
108	
109	  // Immediate execution, no precedence: each operator key first finishes the
110	  // waiting operation, strictly left to right, so the display always shows a
111	  // real running result. 2 + 3 × 4 = is 20, not 14.
112	  function pressOp(op) {
113	    if (state.error) return;
114	    resolve();
115	    if (state.error) return;
116	    state.acc = state.value;
117	    state.op = op;
118	    state.entry = null;
119	  }
120	
121	  function pressEquals() {
122	    if (state.error) return;
123	    resolve();
124	    state.acc = null;
125	    state.op = null;
126	    state.entry = null;
127	  }
128	
129	  function clear() {
130	    state = { acc: null, op: null, entry: null, value: 0, error: false };
131	  }
132	
133	  var display = document.querySelector('[data-testid="calc-display"]');
134	
135	  function render() {
136	    display.setAttribute('data-value', String(state.value));
137	    display.setAttribute('data-error', state.error ? 'true' : 'false');
138	    if (state.error) display.textContent = 'Error';
139	    else display.textContent = state.entry !== null ? state.entry : formatNumber(state.value);
140	  }
141	
142	  document.querySelector('.keys').addEventListener('click', function (e) {
143	    var b = e.target.closest('button');
144	    if (!b) return;
145	    if (b.dataset.digit !== undefined) pressDigit(b.dataset.digit);
146	    else if (b.dataset.op) pressOp(b.dataset.op);
147	    else if (b.dataset.action === 'dot') pressDot();
148	    else if (b.dataset.action === 'equals') pressEquals();
149	    else if (b.dataset.action === 'clear') clear();
150	    render();
151	  });
152	
153	  render();
154	</script>
155	</body>
156	</html>
